import { InsufficientStockError, NotFoundError } from "./errors";
import { OrderItem } from "./order-item";
import { Product } from "./product";
import { ProductRepository } from "./product-repository";

export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  /** Reserves every item or none of them. */
  async reserve(items: readonly OrderItem[]): Promise<void> {
    const needed = new Map<string, number>();
    for (const item of items) {
      needed.set(item.productId, (needed.get(item.productId) ?? 0) + item.quantity);
    }
    const loaded: Array<[Product, number]> = [];
    for (const [productId, quantity] of needed) {
      const product = await this.products.findById(productId);
      if (!product) throw new NotFoundError(`Product ${productId} not found`);
      if (!product.canReserve(quantity)) {
        throw new InsufficientStockError(`Insufficient stock for product ${productId}`);
      }
      loaded.push([product, quantity]);
    }
    for (const [product, quantity] of loaded) {
      product.reserve(quantity);
      await this.products.save(product);
    }
  }

  async release(items: readonly OrderItem[]): Promise<void> {
    for (const item of items) {
      const product = await this.products.findById(item.productId);
      if (!product) continue;
      product.release(item.quantity);
      await this.products.save(product);
    }
  }
}

